(5656891, 822511, 30982, '<td valign="top">Gorgeous use of OOF - the fence creates the gridded overlay; the light is wonderful behind the creature, and you can still see the eyes.  Very lovely!</td>', 'Gorgeous use of OOF - the fence creates the gridded overlay; the light is wonderful behind the creature, and you can still see the eyes.  Very lovely!', '2009-09-22 04:23:10.000000', NULL, 1),
(5656892, 822686, 30982, '<td valign="top">I''d love to see this with just a touch more light in it - not necessarily a whole lot.  Very unique approach to the challenge!</td>', 'I''d love to see this with just a touch more light in it - not necessarily a whole lot.  Very unique approach to the challenge!', '2009-09-22 04:24:35.000000', NULL, 1),
(5656893, 822532, 30982, '<td valign="top">This is delightfully corny, but in a sweet way.  "And the two shall be one" imagery with the tree, even!  OOF works to tell the tale.</td>', 'This is delightfully corny, but in a sweet way.  "And the two shall be one" imagery with the tree, even!  OOF works to tell the tale.', '2009-09-22 04:25:43.000000', NULL, 1),
(5656894, 822437, 30982, '<td valign="top">Interesting color result!</td>', 'Interesting color result!', '2009-09-22 04:26:31.000000', NULL, 1),
(5656895, 822459, 30982, '<td valign="top">I''m thinking a dog with a long nose, wearing a hat?  The hat portion needs a bit more light - right now it is kind of a dark hole sucking everything into it.</td>', 'I''m thinking a dog with a long nose, wearing a hat?  The hat portion needs a bit more light - right now it is kind of a dark hole sucking everything into it.', '2009-09-22 04:28:10.000000', NULL, 1),
(5656896, 822542, 30982, '<td valign="top">Perfectly focused, which kinda defeats the point of the challenge.  One could assume you missed the focus on the girl, but if one were focusing on the girl, why would she have a frog on her finger in front of her face, would be my question?  Or should there have been a deeper depth of field to get both in focus?  At any rate, I''ll skip voting on this one - great shot, but not what the challenge probably intended.</td>', 'Perfectly focused, which kinda defeats the point of the challenge.  One could assume you missed the focus on the girl, but if one were focusing on the girl, why would she have a frog on her finger in front of her face, would be my question?  Or should there have been a deeper depth of field to get both in focus?  At any rate, I''ll skip voting on this one - great shot, but not what the challenge probably intended.', '2009-09-22 04:29:45.000000', NULL, 1),
(5656898, 822481, 30982, '<td valign="top">Lovely use of color and blur.  Some would argue your subject is most definitely in focus, though.</td>', 'Lovely use of color and blur.  Some would argue your subject is most definitely in focus, though.', '2009-09-22 04:31:15.000000', NULL, 1),
(5656911, 822434, 27133, '<td valign="top">Whoa...this is soo blurry I can''t even see the main subject.  LOL!</td>', 'Whoa...this is soo blurry I can''t even see the main subject.  LOL!', '2009-09-22 05:39:07.000000', NULL, 1),
(5656912, 822695, 27133, '<td valign="top">Now this definitely fits the challenge.</td>', 'Now this definitely fits the challenge.', '2009-09-22 05:39:19.000000', NULL, 1),
(5656913, 822660, 27133, '<td valign="top">The fun fungus looks funny...or is that funky?</td>', 'The fun fungus looks funny...or is that funky?', '2009-09-22 05:39:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5656914, 822455, 27133, '<td valign="top">Oooh.....my eyes would be blurry if I had to wear that colour.  Hehehe!</td>', 'Oooh.....my eyes would be blurry if I had to wear that colour.  Hehehe!', '2009-09-22 05:39:58.000000', NULL, 1),
